<?php
require 'config.php'; require_login();
$site=$pdo->query("SELECT * FROM sites ORDER BY id DESC LIMIT 1")->fetch();
$stats=$pdo->query("SELECT COUNT(*) runs, COALESCE(SUM(total_pages_crawled),0) pages, COALESCE(SUM(total_links_found),0) links, COALESCE(SUM(total_errors),0) errors FROM scan_runs")->fetch();
$recent=$pdo->query("SELECT r.id,r.started_at,r.status,r.total_links_found,r.total_errors,s.name,s.start_url FROM scan_runs r JOIN sites s ON s.id=r.site_id ORDER BY r.id DESC LIMIT 5")->fetchAll();
$trend=$pdo->query("SELECT DATE(started_at) day, COUNT(*) runs, COALESCE(SUM(total_errors),0) errors FROM scan_runs WHERE started_at >= DATE_SUB(CURDATE(), INTERVAL 6 DAY) GROUP BY DATE(started_at) ORDER BY day")->fetchAll();
$notifications=$pdo->query("SELECT COUNT(*) FROM notifications WHERE is_read=0")->fetchColumn();
layout_start('Tổng quan'); ?>
